def ensure_dir(path):
    if not editor_asset_lib.does_directory_exist(path):
        editor_asset_lib.make_directory(path)


def find_class(name):
    """Resolve a UCLASS by name (works for native C++ classes once compiled)."""
    modules_to_try = []
    try:
        project_path = unreal.Paths.get_project_file_path()
        if project_path:
            module = os.path.splitext(os.path.basename(project_path))[0]
            modules_to_try.append(module)
    except Exception:
        pass
    modules_to_try.append("Game")
    modules_to_try.append("GameCore")

    for module in modules_to_try:
        cls = unreal.load_class(None, f"/Script/{module}.{name}")
        if cls:
            return cls
    raise RuntimeError(
        f"Could not resolve class '{name}'. Make sure the C++ module compiled "
        f"successfully (the project must have been built at least once)."
    )


def class_available(name):
    """Return True if the C++ class is registered, without raising."""
    try:
        find_class(name)
        return True
    except RuntimeError:
        return False


def _load_project_module():
    """Force-load the project module so reflected types (enums, structs, etc.)
    become available to Python."""
    try:
        project_path = unreal.Paths.get_project_file_path()
        if project_path:
            mod_name = os.path.splitext(os.path.basename(project_path))[0]
            world = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()
            if world:
                unreal.SystemLibrary.execute_console_command(world, f"Module.Load {mod_name}")
                time.sleep(0.5)
    except Exception:
        pass


def _project_source_dir():
    """Return the project's Source/<Module> directory."""
    project_path = unreal.Paths.get_project_file_path()
    if not project_path:
        return None
    project_dir = os.path.dirname(project_path)
    module_name = os.path.splitext(os.path.basename(project_path))[0]
    return os.path.join(project_dir, "Source", module_name)


def _write_module_file(dst_dir, fname, content, written):
    dst = os.path.join(dst_dir, fname)
    data = content.encode("utf-8")
    if os.path.exists(dst):
        with open(dst, "rb") as fh:
            if fh.read() == data:
                return written
    with open(dst, "wb") as fh:
        fh.write(data)
    return written + 1

def copy_cpp_sources():
    """Write embedded C++ source files and minimal module infra into the project's Source directory."""
    dst_dir = _project_source_dir()
    if not dst_dir:
        unreal.log_warning("[MANUAL] Could not determine project source directory")
        return -1

    os.makedirs(dst_dir, exist_ok=True)

    # Prefer files from the script's directory (development), fall back to embedded
    script_dir = os.path.dirname(os.path.abspath(__file__))

    written = 0
    for fname, data_bytes in EMBEDDED_SOURCES.items():
        dst = os.path.join(dst_dir, fname)
        src = os.path.join(script_dir, fname)
        if os.path.isfile(src):
            with open(src, "rb") as fh:
                data = fh.read()
        else:
            data = data_bytes
        needs_write = True
        if os.path.isfile(dst):
            with open(dst, "rb") as fh:
                if fh.read() == data:
                    needs_write = False
        if needs_write:
            with open(dst, "wb") as fh:
                fh.write(data)
            written += 1
        else:
            pass  # unchanged

    # Generate module infrastructure if missing (fresh Blueprint project)
    project_path = unreal.Paths.get_project_file_path()
    if project_path:
        mod_name = os.path.splitext(os.path.basename(project_path))[0]
        build_cs = f'{mod_name}.Build.cs'
        mod_h = f'{mod_name}.h'

        build_cs_content = f'''using UnrealBuildTool;

public class {mod_name} : ModuleRules
{{
    public {mod_name}(ReadOnlyTargetRules Target) : base(Target)
    {{
        PCHUsage = PCHUsageMode.UseExplicitOrSharedPCHs;

        PublicDependencyModuleNames.AddRange(new string[] {{
            "Core",
            "CoreUObject",
            "Engine",
            "InputCore",
            "ProceduralMeshComponent",
        }});

        PrivateDependencyModuleNames.AddRange(new string[] {{
            "Slate",
            "SlateCore",
            "UMG",
        }});
    }}
}}'''
        written = _write_module_file(dst_dir, build_cs, build_cs_content, written)

        mod_h_content = f'''#pragma once

#include "CoreMinimal.h"
#include "Modules/ModuleInterface.h"
#include "Modules/ModuleManager.h"

class MYPROJECT_API F{mod_name}Module : public IModuleInterface
{{
public:
    virtual void StartupModule() override;
    virtual void ShutdownModule() override;
}};
'''
        written = _write_module_file(dst_dir, mod_h, mod_h_content, written)

        mod_cpp = f'{mod_name}.cpp'
        mod_cpp_content = f'''#include "{mod_name}.h"

void F{mod_name}Module::StartupModule()
{{
}}

void F{mod_name}Module::ShutdownModule()
{{
}}

IMPLEMENT_MODULE(F{mod_name}Module, {mod_name});
'''
        written = _write_module_file(dst_dir, mod_cpp, mod_cpp_content, written)

        # Generate TargetRules files if they don't exist
        source_dir = os.path.join(os.path.dirname(project_path), "Source")
        target_game = f'{mod_name}.Target.cs'
        target_game_content = f'''using UnrealBuildTool;
using System.Collections.Generic;

public class {mod_name}Target : TargetRules
{{
    public {mod_name}Target(TargetInfo Target) : base(Target)
    {{
        Type = TargetType.Game;
        DefaultBuildSettings = BuildSettingsVersion.V7;
        ExtraModuleNames.AddRange(new string[] {{ "{mod_name}" }});
    }}
}}'''
        written = _write_module_file(source_dir, target_game, target_game_content, written)

        target_editor = f'{mod_name}Editor.Target.cs'
        target_editor_content = f'''using UnrealBuildTool;
using System.Collections.Generic;

public class {mod_name}EditorTarget : TargetRules
{{
    public {mod_name}EditorTarget(TargetInfo Target) : base(Target)
    {{
        Type = TargetType.Editor;
        DefaultBuildSettings = BuildSettingsVersion.V7;
        ExtraModuleNames.AddRange(new string[] {{ "{mod_name}" }});
    }}
}}'''
        written = _write_module_file(source_dir, target_editor, target_editor_content, written)

    if written:
        unreal.log(f"[OK] Wrote {written} C++ file(s) to {dst_dir}")
    else:
        unreal.log(f"[OK] C++ source files already up to date in {dst_dir}")
    return written


def _ensure_dirs_for(path):
    d = os.path.dirname(path)
    os.makedirs(d, exist_ok=True)

def _ensure_project_plugins(project_path):
    """Add required plugins to .uproject's Plugins array; remove deprecated ones."""
    import json as _json
    required = {"ProceduralMeshComponent", "EditorScriptingUtilities"}
    deprecated = {"Blutility"}
    try:
        with open(project_path, "r") as f:
            uproj = _json.load(f)
        plugins = uproj.get("Plugins", [])
        existing = {p.get("Name") for p in plugins}
        changed = False
        for name in required:
            if name not in existing:
                plugins.append({"Name": name, "Enabled": True})
                changed = True
        plugins = [p for p in plugins if p.get("Name") not in deprecated]
        if len(plugins) != len(uproj.get("Plugins", [])):
            changed = True
        if changed:
            uproj["Plugins"] = plugins
            with open(project_path, "w") as f:
                _json.dump(uproj, f, indent=4)
            unreal.log(f"[OK] Updated plugins in .uproject")
    except Exception as e:
        unreal.log_warning(f"[COMPILE] Could not update plugins in .uproject: {e}")

def _add_module_to_project(project_path, module_name):
    """Register module in .uproject so the engine loads it at startup.
    Uses PostDefault so all Default-phase plugin modules (e.g.
    ProceduralMeshComponent) finish UClass registration first."""
    import json as _json
    try:
        with open(project_path, "r") as f:
            uproj = _json.load(f)
        modules = uproj.get("Modules", [])
        for m in modules:
            if m.get("Name") == module_name:
                if m.get("LoadingPhase") != "PostDefault":
                    m["LoadingPhase"] = "PostDefault"
                    with open(project_path, "w") as f:
                        _json.dump(uproj, f, indent=4)
                    unreal.log(f"[OK] Updated '{module_name}' LoadingPhase to PostDefault")
                return
        modules.append({
            "Name": module_name,
            "Type": "Runtime",
            "LoadingPhase": "PostDefault",
        })
        uproj["Modules"] = modules
        with open(project_path, "w") as f:
            _json.dump(uproj, f, indent=4)
        unreal.log(f"[OK] Added module '{module_name}' with LoadingPhase=PostDefault")
    except Exception as e:
        unreal.log_warning(f"[COMPILE] Could not update .uproject: {e}")

def _patch_livecoding_json_full(json_path, module_name):
    """Read LiveCoding.json written by UBT, fill in ALL fields the
    UE5.8 LiveCoding parser requires (LinkerPath, module Inputs, etc.).
    Also reads LiveCodingModules.json for correct module structure."""
    import json as _json
    try:
        with open(json_path, "r") as f:
            data = _json.load(f)
    except Exception:
        return

    eng = os.path.dirname(os.path.dirname(json_path))
    changed = False

    # --- LinkerPath ---
    if "LinkerPath" not in data:
        link_path = os.path.join(
            eng, "Intermediate", "Build", "Win64",
            "UnrealEditor", "Development", "UnrealEditor.link")
        data["LinkerPath"] = link_path.replace("\\", "/")
        _ensure_dirs_for(link_path)
        if not os.path.exists(link_path):
            with open(link_path, "w") as _:
                pass
        changed = True

    # --- Modules — copy fields from LiveCodingModules.json if available,
    #     otherwise supply enough to pass parsing.
    lc_modules_path = os.path.join(
        os.path.dirname(json_path), "LiveCodingModules.json")
    ref_modules = {}
    try:
        with open(lc_modules_path, "r") as f:
            lc_data = _json.load(f)
        for m in lc_data.get("Modules", []):
            ref_modules[m.get("Name")] = m
    except Exception:
        pass

    if "Modules" not in data:
        data["Modules"] = []
        changed = True

    if not any(m.get("Name") == module_name for m in data["Modules"]):
        out_dll = os.path.join(
            eng, "Binaries", "Win64",
            f"{module_name}Editor-LiveCoding.dll").replace("\\", "/")
        entry = {"Name": module_name, "Output": out_dll}
        # Copy known-good fields from LiveCodingModules.json
        ref = ref_modules.get(module_name, {})
        for key in ("Inputs", "Dependencies", "ForceWeakRoots",
                     "PrecompiledModuleRequests", "LinkerObjects"):
            if key in ref:
                entry[key] = ref[key]
        # Supply defaults for required fields if still missing
        entry.setdefault("Inputs", [])
        entry.setdefault("Dependencies", [])
        entry.setdefault("ForceWeakRoots", False)
        data["Modules"].append(entry)
        changed = True

    if changed:
        with open(json_path, "w") as f:
            _json.dump(data, f, indent=4)
        unreal.log("[COMPILE] Patched LiveCoding.json with all required fields")


def compile_cpp_module():
    """Compile the C++ module so FaceParallax classes become available.
    Returns True if classes are available after compilation."""
    written = copy_cpp_sources()
    if written < 0:
        return False
    if written == 0 and class_available(PRESET_CLASS_NAME):
        unreal.log("[OK] C++ classes already available and sources unchanged")
        return True

    if written > 0:
        unreal.log(f"[COMPILE] {written} source file(s) updated — forcing recompilation")
    else:
        unreal.log("[COMPILE] C++ classes not found. Compiling...")

    project_path = unreal.Paths.get_project_file_path()
    if not project_path:
        unreal.log_warning("[MANUAL] Cannot resolve project path")
        return False

    module_name = os.path.splitext(os.path.basename(project_path))[0]

    # If no sources changed and the module is already compiled, load it directly
    if written == 0:
        for mod_name in [module_name, f"{module_name}Editor", f"{module_name}Editor-LiveCoding"]:
            try:
                world = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()
                if world:
                    unreal.SystemLibrary.execute_console_command(world, f"Module.Load {mod_name}")
                    time.sleep(1)
                    if class_available(PRESET_CLASS_NAME):
                        unreal.log(f"[OK] C++ classes available after loading '{mod_name}'")
                        return True
            except Exception:
                pass

    # Ensure .uproject has module entry + required plugins
    _add_module_to_project(project_path, module_name)
    _ensure_project_plugins(project_path)
    try:
        world = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()
        if world:
            unreal.SystemLibrary.execute_console_command(world,
                f"Project.AddModule {module_name} Development Default")
    except Exception:
        pass

    # Check if project DLL already exists
    project_dir = os.path.dirname(project_path)
    dll_path = os.path.join(project_dir, "Binaries", "Win64", f"UnrealEditor-{module_name}.dll")
    dll_exists = os.path.exists(dll_path)

    if dll_exists and written == 0:
        # DLL exists with no source changes — use LiveCoding.Compile for incremental changes
        engine_intermediate = os.path.join(unreal.Paths.engine_dir(), "Intermediate")
        lc_json_path = os.path.join(engine_intermediate, "LiveCoding.json")
        lc_last_mtime = 0
        try:
            world = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()
            if world:
                unreal.log("[COMPILE] DLL exists — using LiveCoding.Compile")
                unreal.SystemLibrary.execute_console_command(world, "LiveCoding.Compile")
                unreal.log("[COMPILE] Waiting up to 10 minutes for build...")
                for _ in range(600):
                    time.sleep(1)
                    if class_available(PRESET_CLASS_NAME):
                        unreal.log("[OK] C++ classes available after LiveCoding.Compile")
                        return True
                    if os.path.exists(lc_json_path):
                        mtime = os.path.getmtime(lc_json_path)
                        if mtime > lc_last_mtime:
                            lc_last_mtime = mtime
                            _patch_livecoding_json_full(lc_json_path, module_name)
                unreal.log("[COMPILE] LiveCoding.Compile did not finish in 10 min")
        except Exception as e:
            unreal.log(f"[COMPILE] LiveCoding.Compile failed: {e}")
        # LiveCoding failed — try loading existing module
    elif dll_exists and written > 0:
        unreal.log("[COMPILE] DLL exists with source changes — trying Module.Load...")
        for mod_name in [module_name, f"{module_name}Editor", f"{module_name}Editor-LiveCoding"]:
            try:
                world = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()
                if world:
                    unreal.SystemLibrary.execute_console_command(world, f"Module.Load {mod_name}")
                    time.sleep(1)
                    if class_available(PRESET_CLASS_NAME):
                        unreal.log(f"[OK] C++ classes available after loading '{mod_name}'")
                        return True
            except Exception:
                pass
        unreal.log("[MANUAL] Module.Load did not expose classes.\n"
                   "   If you built from Visual Studio / UBT, run deploy again (sources are now up to date).\n"
                   f"   Open {module_name}.sln and build '{module_name}Editor' (Development Editor).")
        return False
    else:
        unreal.log("[MANUAL] Project DLL not found.\n"
                   "   Build from Visual Studio once to create the initial DLL, then run deploy again.\n"
                   f"   Open {module_name}.sln and build '{module_name}Editor' (Development Editor).")
        return False

    # Module.Load after LiveCoding — registers classes if hot-reload didn't
    for mod_name in [module_name, f"{module_name}Editor", f"{module_name}Editor-LiveCoding"]:
        try:
            world = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()
            if world:
                unreal.SystemLibrary.execute_console_command(world, f"Module.Load {mod_name}")
                time.sleep(2)
                if class_available(PRESET_CLASS_NAME):
                    unreal.log(f"[OK] C++ classes available after Module.Load {mod_name}")
                    return True
        except Exception:
            pass

    # One more check if LiveCoding applied but Module.Load wasn't needed
    if class_available(PRESET_CLASS_NAME):
        return True

    unreal.log_warning(
        "[MANUAL] LiveCoding.Compile applied but classes not yet available.\n"
        "   Wait a moment or restart the editor and run deploy.py again."
    )
    return False


# --------------------------------------------------------------
# 1. Master Material
# --------------------------------------------------------------
def create_master_material():
    mat_path = f"{CONTENT_ROOT}/Materials"
    ensure_dir(mat_path)

    mat_name = "M_FaceParallax_Master"
    full_path = f"{mat_path}/{mat_name}"

    if editor_asset_lib.does_asset_exist(full_path):
        unreal.log(f"[SKIP] {full_path} already exists")
        return unreal.load_asset(full_path)

    factory = unreal.MaterialFactoryNew()
    material = asset_tools.create_asset(mat_name, mat_path, unreal.Material, factory)

    mel = unreal.MaterialEditingLibrary

    def tex_param(name, x, y):
        node = mel.create_material_expression(material, unreal.MaterialExpressionTextureSampleParameter2D, x, y)
        node.set_editor_property("parameter_name", name)
        return node

    def scalar_param(name, x, y, default=0.0):
        node = mel.create_material_expression(material, unreal.MaterialExpressionScalarParameter, x, y)
        node.set_editor_property("parameter_name", name)
        node.set_editor_property("default_value", default)
        return node

    def vec_param(name, x, y):
        node = mel.create_material_expression(material, unreal.MaterialExpressionVectorParameter, x, y)
        node.set_editor_property("parameter_name", name)
        return node

    def static_switch(name, x, y, default=False):
        node = mel.create_material_expression(material, unreal.MaterialExpressionStaticBoolParameter, x, y)
        node.set_editor_property("parameter_name", name)
        node.set_editor_property("default_value", default)
        return node

    # --- Parameters (mirrors the checklist's parameter list) ---
    albedo_cur   = tex_param("AlbedoTexture",     -600, -300)
    albedo_prev  = tex_param("AlbedoTexturePrev",  -600, -150)
    normal_cur   = tex_param("NormalTexture",      -600,    0)
    normal_prev  = tex_param("NormalTexturePrev",  -600,  150)
    depth_cur    = tex_param("DepthTexture",       -600,  300)
    depth_prev   = tex_param("DepthTexturePrev",   -600,  450)

    blend_alpha  = scalar_param("StateBlendAlpha", -600, 600, 0.0)
    parallax_off = vec_param("ParallaxOffset",     -600, 750)
    art_pos      = vec_param("ArtPosition",         -600, 900)
    art_scale    = vec_param("ArtScale",             -600, 1050)
    art_rot      = scalar_param("ArtRotation",       -600, 1200, 0.0)
    depth_int    = scalar_param("DepthIntensity",    -600, 1350, 1.0)
    debug_depth  = static_switch("DebugDepth",       -600, 1500, False)
    is_topdown   = static_switch("IsTopDown",        -600, 1650, False)
    is_topview   = static_switch("IsTopView",        -600, 1800, False)

    art_pivot    = vec_param("ArtPivot",              -600, 1950)
    nested_frame = scalar_param("NestedAnimFrame",    -600, 2100, 0.0)

    expr_alpha   = scalar_param("ExpressionBlendAlpha", -600, 2250, 0.0)
    expr_alb_prev = tex_param("ExpressionAlbedoPrev",  -600, 2400)
    expr_nrm_prev = tex_param("ExpressionNormalPrev",  -600, 2550)
    expr_dep_prev = tex_param("ExpressionDepthPrev",   -600, 2700)

    # --- UV: pan by ParallaxOffset scaled with ArtPosition/ArtScale ---
    texcoord = mel.create_material_expression(material, unreal.MaterialExpressionTextureCoordinate, -1000, -300)
    uv_add_pos = mel.create_material_expression(material, unreal.MaterialExpressionAdd, -850, -300)
    mel.connect_material_expressions(texcoord, "", uv_add_pos, "A")
    mel.connect_material_expressions(art_pos, "", uv_add_pos, "B")

    uv_mul_scale = mel.create_material_expression(material, unreal.MaterialExpressionMultiply, -750, -300)
    mel.connect_material_expressions(uv_add_pos, "", uv_mul_scale, "A")
    mel.connect_material_expressions(art_scale, "", uv_mul_scale, "B")

    uv_final = mel.create_material_expression(material, unreal.MaterialExpressionAdd, -680, -280)
    mel.connect_material_expressions(uv_mul_scale, "", uv_final, "A")
    mel.connect_material_expressions(parallax_off, "", uv_final, "B")

    for tex_node in (albedo_cur, albedo_prev, normal_cur, normal_prev, depth_cur, depth_prev):
        mel.connect_material_expressions(uv_final, "", tex_node, "UVs")

    # --- Crossfade current/prev per channel via StateBlendAlpha ---
    def lerp(a, b, alpha, x, y):
        node = mel.create_material_expression(material, unreal.MaterialExpressionLinearInterpolate, x, y)
        mel.connect_material_expressions(a, "", node, "A")
        mel.connect_material_expressions(b, "", node, "B")
        mel.connect_material_expressions(alpha, "", node, "Alpha")
        return node

    albedo_blend = lerp(albedo_prev, albedo_cur, blend_alpha, -300, -250)
    normal_blend = lerp(normal_prev, normal_cur, blend_alpha, -300, 50)
    depth_blend  = lerp(depth_prev, depth_cur, blend_alpha, -300, 350)

    depth_scaled = mel.create_material_expression(material, unreal.MaterialExpressionMultiply, -150, 350)
    mel.connect_material_expressions(depth_blend, "", depth_scaled, "A")
    mel.connect_material_expressions(depth_int, "", depth_scaled, "B")

    # DebugDepth switch: show raw depth in place of albedo when enabled
    debug_switch = mel.create_material_expression(material, unreal.MaterialExpressionStaticSwitch, 50, -100)
    mel.connect_material_expressions(debug_depth, "", debug_switch, "Value")
    mel.connect_material_expressions(depth_scaled, "", debug_switch, "True")
    mel.connect_material_expressions(albedo_blend, "", debug_switch, "False")

    mel.connect_material_property(debug_switch, unreal.MaterialProperty.MP_BASE_COLOR, 0)
    mel.connect_material_property(normal_blend, unreal.MaterialProperty.MP_NORMAL, 0)

    mel.recompile_material(material)
    editor_asset_lib.save_asset(full_path)
    unreal.log(f"[OK] Created {full_path} with wired parameter graph")
    return material


# --------------------------------------------------------------
# 2. Material Instances per layer
# --------------------------------------------------------------
def create_material_instances(master_material):
    mi_path = f"{CONTENT_ROOT}/Materials/Instances"
    ensure_dir(mi_path)

    instances = {}
    for layer_tag, *_ in LAYERS:
        name = f"MI_FaceParallax_{layer_tag}"
        full_path = f"{mi_path}/{name}"
        if editor_asset_lib.does_asset_exist(full_path):
            unreal.log(f"[SKIP] {full_path} already exists")
            instances[layer_tag] = unreal.load_asset(full_path)
            continue

        factory = unreal.MaterialInstanceConstantFactoryNew()
        mi = asset_tools.create_asset(name, mi_path, unreal.MaterialInstanceConstant, factory)
        unreal.MaterialEditingLibrary.set_material_instance_parent(mi, master_material)
        editor_asset_lib.save_asset(full_path)
        unreal.log(f"[OK] Created {full_path} (parent: {master_material.get_name()})")
        instances[layer_tag] = mi
    return instances


# --------------------------------------------------------------
# 3. FaceParallaxPreset Data Asset
# --------------------------------------------------------------
def create_preset_asset():
    preset_path = f"{CONTENT_ROOT}/Presets"
    ensure_dir(preset_path)

    name = "DA_FaceParallax_Default"
    full_path = f"{preset_path}/{name}"

    preset_class = find_class(PRESET_CLASS_NAME)

    if editor_asset_lib.does_asset_exist(full_path):
        existing = unreal.load_asset(full_path)
        # Try to populate ViewAssignments if empty
        try:
            current = existing.get_editor_property("ViewAssignments")
            if not current or len(current) == 0:
                _populate_preset_assignments(existing)
                editor_asset_lib.save_asset(full_path)
                unreal.log(f"[OK] Populated empty ViewAssignments on existing {full_path}")
            else:
                unreal.log(f"[SKIP] {full_path} already exists with {len(current)} assignments")
        except Exception:
            unreal.log(f"[SKIP] {full_path} already exists")
        return existing

    factory = unreal.DataAssetFactory()
    factory.set_editor_property("data_asset_class", preset_class)
    preset = asset_tools.create_asset(name, preset_path, preset_class, factory)
    try:
        _populate_preset_assignments(preset)
        unreal.log("[OK] Populated ViewAssignments for all states")
    except Exception as e:
        unreal.log_warning(
            f"[MANUAL] Could not auto-populate ViewAssignments ({e}). "
            f"Open {full_path} in the Editor and populate the map manually."
        )
    editor_asset_lib.save_asset(full_path)
    unreal.log(f"[OK] Created {full_path}")
    return preset


def _populate_preset_assignments(preset):
    """Fill ViewAssignments TMap with default empty FFaceArtSlot entries."""
    # Force the C++ module to load so reflected types (EFaceAngleState) are available
    _load_project_module()
    assignments = {}
    for view_name in VIEW_STATES:
        try:
            view_enum = getattr(unreal.EFaceAngleState, view_name)
        except AttributeError:
            raise RuntimeError(f"EFaceAngleState.{view_name} not available")
        layer_set = unreal.FFaceViewStateLayerSet()
        layers = {}
        for layer_tag, *_ in LAYERS:
            slot = unreal.FFaceArtSlot()
            layers[unreal.Name(layer_tag)] = slot
        layer_set.set_editor_property("Layers", layers)
        assignments[view_enum] = layer_set
    preset.set_editor_property("ViewAssignments", assignments)


# --------------------------------------------------------------
# 4. Character Blueprint with FaceParallaxComponent wired up
# --------------------------------------------------------------
def _wiring_needs_repair(blueprint, component_class):
    """Check if the character BP is missing the component or mesh."""
    try:
        bp_class = blueprint.get_class()
        if not bp_class:
            return True
        cdo = unreal.get_default_object(bp_class)
        if not cdo:
            return True
        mesh_comp = cdo.get_editor_property("Mesh")
        if not mesh_comp:
            return True
        return False
    except Exception:
        return True


def _compile_blueprint(blueprint):
    """Force compile a Blueprint asset and wait for completion."""
    try:
        blueprint.compile()
        unreal.AssetRegistryHelpers.get_asset_registry().on_asset_updated(blueprint.package_path)
        return True
    except Exception:
        return False


def _resolve_character_parent():
    """Resolve the Character parent class; UE5 Python may not expose unreal.Character directly."""
    for path in ("/Script/Engine.Character", "/Script/Engine.Character"):
        try:
            cls = unreal.load_class(None, path)
            if cls:
                return cls
        except Exception:
            continue
    unreal.log_warning("[MANUAL] Could not resolve Character parent class — using default")
    return unreal.Actor


def create_character_blueprint(preset_asset):
    ensure_dir(CHARACTER_OUTPUT_PATH)

    full_path = f"{CHARACTER_OUTPUT_PATH}/{CHARACTER_BP_NAME}"
    _load_project_module()
    component_class = find_class(COMPONENT_CLASS_NAME)
    parent_class = _resolve_character_parent()

    # Load mannequin assets (use fallback paths for UE5)
    mannequin_mesh = None
    mannequin_anim = None
    for mesh_path in [MANNEQUIN_SKELETAL_MESH,
                      "/Game/Characters/Mannequins/Meshes/SK_Mannequin.SK_Mannequin",
                      "/Script/Engine.SkeletalMesh'/Game/Characters/Mannequins/Meshes/SK_Mannequin.SK_Mannequin'"]:
        try:
            mannequin_mesh = unreal.load_asset(mesh_path)
            if mannequin_mesh:
                break
        except Exception:
            continue
    for anim_path in [MANNEQUIN_ANIM_BLUEPRINT,
                      "/Game/Characters/Mannequins/Animations/ABP_Mannequin.ABP_Mannequin",
                      "/Game/Mannequin/Animations/ABP_Mannequin.ABP_Mannequin"]:
        try:
            mannequin_anim = unreal.load_asset(anim_path)
            if mannequin_anim:
                break
        except Exception:
            continue
    if not mannequin_mesh:
        unreal.log_warning(f"[MANUAL] Could not load SK_Mannequin mesh")

    if editor_asset_lib.does_asset_exist(full_path):
        existing = unreal.load_asset(full_path)
        if not _wiring_needs_repair(existing, component_class):
            unreal.log(f"[SKIP] {full_path} already exists and appears correctly wired")
            return existing
        unreal.log(f"[REPLACE] {full_path} exists but needs rewiring — replacing")
        editor_asset_lib.delete_asset(full_path)

    factory = unreal.BlueprintFactory()
    factory.set_editor_property("parent_class", parent_class)
    blueprint = asset_tools.create_asset(CHARACTER_BP_NAME, CHARACTER_OUTPUT_PATH, unreal.Blueprint, factory)

    # Compile and wait for the generated class to be ready
    _compile_blueprint(blueprint)
    # Force a second compile to ensure CDO is populated with inherited properties
    _compile_blueprint(blueprint)

    # The Character parent already has a Mesh component — assign the skel mesh to it
    if mannequin_mesh:
        try:
            bp_gc = blueprint.get_generated_class()
            if bp_gc:
                cdo = unreal.get_default_object(bp_gc)
                mesh_comp = cdo.get_editor_property("Mesh")
                if mesh_comp:
                    mesh_comp.set_editor_property("skeletal_mesh", mannequin_mesh)
                    if mannequin_anim:
                        mesh_comp.set_editor_property("anim_class", mannequin_anim)
                    unreal.log("[OK] Assigned SK_Mannequin to Mesh component")
                else:
                    bp_obj = unreal.load_asset(full_path)
                    if bp_obj:
                        bp_gc2 = bp_obj.get_generated_class()
                        if bp_gc2:
                            cdo2 = unreal.get_default_object(bp_gc2)
                            unreal.log(f"[MANUAL] CDO class: {cdo2.get_class().get_name()}")
        except Exception as e:
            unreal.log_warning(f"[MANUAL] Could not assign mannequin mesh ({e})")

    # Add FaceParallaxComponent — try known Blueprint APIs
    if component_class:
        comp_added = False
        # Method 1: BlueprintEditorLibrary (reliable in most UE5 builds)
        try:
            lib = unreal.BlueprintEditorLibrary
            if hasattr(lib, "add_component_to_blueprint"):
                lib.add_component_to_blueprint(blueprint, component_class, "FaceParallax")
                comp_added = True
        except Exception:
            pass
        # Method 2: SubobjectDataSubsystem fallback
        if not comp_added:
            try:
                sub_sys = None
                try:
                    sub_sys = unreal.get_editor_subsystem(unreal.SubobjectDataSubsystem.static_class())
                except Exception:
                    cls = unreal.load_class(None, "/Script/Blueprint.SubobjectDataSubsystem")
                    if cls:
                        sub_sys = unreal.get_editor_subsystem(cls)
                if sub_sys:
                    root = sub_sys.k2_gather_subobject_data_for_blueprint(blueprint)
                    if root and len(root) > 0:
                        handle, reason = sub_sys.add_new_subobject(unreal.AddNewSubobjectParams(
                            parent_handle=root[0], new_class=component_class, blueprint_context=blueprint))
                        if not reason:
                            sub_sys.rename_subobject(handle, unreal.Text("FaceParallax"))
                            comp_added = True
            except Exception:
                pass
        if comp_added:
            try:
                cdo = unreal.get_default_object(blueprint.get_generated_class())
                for c in cdo.get_editor_property("Components"):
                    if c.get_class() == component_class:
                        try: c.set_editor_property("HeadBoneName", HEAD_BONE_NAME)
                        except Exception: pass
                        try: c.set_editor_property("ActivePreset", preset_asset)
                        except Exception: pass
                        try:
                            defs = [unreal.FFaceLayerDef(
                                layer_tag=unreal.Name(t), depth_scale=s,
                                depth_map_intensity=i, b_invert_parallax=v)
                                for t, s, i, v in LAYERS]
                            c.set_editor_property("LayerDefinitions", defs)
                            unreal.log(f"[OK] Populated {len(defs)} LayerDefinitions entries")
                        except Exception: pass
                        break
            except Exception:
                pass
            unreal.log("[OK] Added FaceParallaxComponent to Blueprint")
        else:
            unreal.log_warning("[MANUAL] Could not auto-add FaceParallaxComponent — "
                               f"add it manually to {full_path}")
    else:
        unreal.log_warning("[MANUAL] FaceParallaxComponent class not found")

    unreal.EditorAssetLibrary.save_loaded_asset(blueprint)
    unreal.log(f"[OK] Created {full_path} with FaceParallaxComponent + SK_Mannequin")
    return blueprint


