# 5. Create Editor Widget Blueprint (UserWidget base, no Blutility)
# --------------------------------------------------------------
def create_editor_widget_blueprint():
    ensure_dir("/Game/FaceParallax/Blueprints")
    full_path = "/Game/FaceParallax/Blueprints/WBP_FaceParallaxEditor"
    widget_class = find_class("FaceParallaxEditorWidget")

    if editor_asset_lib.does_asset_exist(full_path):
        existing = unreal.load_asset(full_path)
        if existing and existing.get_class().get_name() == "WidgetBlueprint":
            try:
                bp_parent = existing.get_editor_property("parent_class")
                if bp_parent and bp_parent == widget_class:
                    unreal.log(f"[SKIP] {full_path} already exists with correct parent class")
                    return existing
                unreal.log(f"[REPLACE] {full_path} parent class mismatch — replacing")
            except Exception:
                unreal.log(f"[REPLACE] {full_path} cannot verify parent class — replacing")
        else:
            unreal.log(f"[REPLACE] {full_path} exists but is not a WidgetBlueprint — replacing")
        editor_asset_lib.delete_asset(full_path)

    try:
        factory = unreal.WidgetBlueprintFactory()
        asset_class = getattr(unreal, "WidgetBlueprint", unreal.Blueprint)
    except AttributeError:
        factory = unreal.BlueprintFactory()
        asset_class = unreal.Blueprint
    factory.set_editor_property("parent_class", widget_class)
    blueprint = asset_tools.create_asset(
        "WBP_FaceParallaxEditor", "/Game/FaceParallax/Blueprints",
        asset_class, factory
    )
    editor_asset_lib.save_loaded_asset(blueprint)
    unreal.log(f"[OK] Created Editor Widget at {full_path}")
    return blueprint


