# 10. Register Editor Toolbar Button (via ToolMenus Python API)
# --------------------------------------------------------------
def register_editor_toolbar():
    try:
        menus = unreal.ToolMenus.get()
        toolbar = menus.find_menu("LevelEditor.LevelEditorToolBar")
        if not toolbar:
            unreal.log_warning("[MANUAL] Could not find LevelEditor toolbar menu")
            return

        # Add section
        section = toolbar.add_section("FaceParallax", "Face Parallax")

        entry = section.add_menu_entry("OpenFaceParallaxEditor", "Face Editor")
        entry.set_editor_property("label", "Face Editor")
        entry.set_editor_property("tooltip", "Open FaceParallax Editor Widget")

        script = (
            'import unreal; '
            'wbp = unreal.load_asset("{}"); '
            'if wbp: '
            '  tc = wbp.get_editor_property("widget_tree"); '
            '  unreal.log("[FaceParallax] Widget ready — open in Designer to edit")'
        ).format(EDITOR_UTILITY_WIDGET_PATH.replace(".WBP_FaceParallaxEditor", ""))
        entry.set_editor_property("on_clicked", lambda: None)
        # Use a simple python exec approach
        unreal.log(f"[TOOLBAR] Added 'Face Editor' button to Level Editor toolbar")
        unreal.log(f"[TOOLBAR] Paste this in Python console to open widget:")
        unreal.log(f'  wbp = unreal.load_asset("{EDITOR_UTILITY_WIDGET_PATH.replace(".WBP_FaceParallaxEditor", "")}")')
        unreal.log(f"  Then open it from Content Browser")

        menus.refresh_all_widgets()
    except Exception as e:
        unreal.log_warning(f"[MANUAL] Could not register toolbar: {e}")


